package com.company.platform.aigateway.application;import java.util.*;import org.springframework.stereotype.Component;@Component public class ToolRegistry{private final Map<String,String> tools=new HashMap<>();public void register(String name,String version){if(name==null||name.isBlank()||version==null)throw new IllegalArgumentException("invalid tool");tools.put(name,version);}public List<Map<String,String>> list(){return tools.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->Map.of("name",e.getKey(),"version",e.getValue())).toList();}}
